choose.when:
delete from collect_interface_statistics where id in (
    select id from collect_interface_statistics where statistics_time < #{beforeTime}
    order by statistics_time, id limit #{limit})

delete from data_processing_statistics where id in (
    select id from data_processing_statistics where statistics_time < #{beforeTime}
    order by statistics_time, id limit #{limit})

delete from sys_monitor_snapshot where id in (
    select id from sys_monitor_snapshot where sample_time < #{beforeTime}
    order by sample_time, id limit #{limit})

delete from sys_runtime_log where id in (
    select id from sys_runtime_log where log_time < #{beforeTime}
    order by log_time, id limit #{limit})

delete from dm_alarm_event where id in (
    select id from dm_alarm_event where alarm_time < #{beforeTime}
    order by alarm_time, id limit #{limit})

delete from sys_alarm_event where id in (
    select id from sys_alarm_event where alarm_time < #{beforeTime}
    order by alarm_time, id limit #{limit})


delete from calib_record_detail where id in (
    select id from calib_record_detail where create_time < #{beforeTime}
    order by create_time, id limit #{limit})

delete from fep_file_transfer_record where id in (
    select id from fep_file_transfer_record where completed_time < #{beforeTime}
    order by completed_time, id limit #{limit})
